CREATE POLICY "Signed-in users can read app files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'app-files');
CREATE POLICY "Admins upload app files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'app-files' AND public.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins update app files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'app-files' AND public.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins delete app files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'app-files' AND public.has_role(auth.uid(), 'admin'::app_role));